	/** 
	 * jumpstart the process by instantiating2 Security
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		securityId = SecurityService.getSecurityInstance()
		.createSecurity( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		SecurityService.getSecurityInstance()
				.createSecurity( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.securitySubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Security : " + successValue.getSecurityId());
							  if (successValue.getSecurityId().equals(securityId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfSecurityList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Security test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on security consumed")
					);
			subscriber.securitySubscribe( securityId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Security : " + successValue.getSecurityId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfSecurityList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on security for securityId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Security. 
	 */
	protected Security read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Security" );

		Security entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Security with primary key" );
		msg.append( securityId );
		
		SecurityFetchOneSummary fetchOneSummary = new SecurityFetchOneSummary( securityId );

		try {
			entity = SecurityService.getSecurityInstance().getSecurity( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Security " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Security.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Security." );

		StringBuilder msg = new StringBuilder( "Failed to update a Security : " );        
		Security entity = read();
		UpdateSecurityCommand command = generateUpdateCommand();
		command.setSecurityId(entity.getSecurityId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Security." );

			// for use later on...
			securityId = entity.getSecurityId();

			SecurityService proxy = SecurityService.getSecurityInstance();  

			proxy.updateSecurity( command ).get();

			LOGGER.info( "-- Successfully saved Security - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + securityId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Security.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Security." );

		Security entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Security with id " + securityId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Security with id " + securityId );

			throw e;
		}

		try{
			SecurityService.getSecurityInstance().delete( new DeleteSecurityCommand( entity.getSecurityId() ) ).get();
			LOGGER.info( "-- Successfully deleted Security with id " + securityId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Security with id " + securityId );

			throw e;
		}
	}

	/**
	 * get all Securitys.
	 */
	protected List<Security> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Securitys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Security : " );        
		List<Security> collection  = new ArrayList<>();

		try {
			// call the static get method on the SecurityService
			collection = SecurityService.getSecurityInstance().getAllSecurity();
			assertNotNull( collection, "An Empty collection of Security was incorrectly returned.");
			
			// Now print out the values
			Security entity = null;            
			Iterator<Security> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getSecurityId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

